describe('Footer Links Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('footer').should('be.visible');
  });

  it('should navigate to correct pages when footer links are clicked', () => {
    const footerLinks = [
      { selector: '[data-testid="footer-about"]', expectedUrl: '/about', expectedTitle: 'About' },
      { selector: '[data-testid="footer-contact"]', expectedUrl: '/contact', expectedTitle: 'Contact' },
      { selector: '[data-testid="footer-privacy"]', expectedUrl: '/privacy', expectedTitle: 'Privacy Policy' },
      { selector: '[data-testid="footer-terms"]', expectedUrl: '/terms', expectedTitle: 'Terms of Service' },
      { selector: '[data-testid="footer-sitemap"]', expectedUrl: '/sitemap', expectedTitle: 'Sitemap' }
    ];

    footerLinks.forEach((link) => {
      cy.visit('/');
      cy.get('footer').should('be.visible');
      cy.get(link.selector).should('be.visible').and('not.be.disabled');
      cy.get(link.selector).click();
      cy.url().should('include', link.expectedUrl);
      cy.get('h1, h2, [data-testid="page-title"]').should('contain', link.expectedTitle);
      cy.get('footer').should('be.visible');
    });
  });

  it('should handle footer links with external URLs correctly', () => {
    const externalLinks = [
      { selector: '[data-testid="footer-facebook"]', expectedUrl: 'facebook.com' },
      { selector: '[data-testid="footer-twitter"]', expectedUrl: 'twitter.com' },
      { selector: '[data-testid="footer-linkedin"]', expectedUrl: 'linkedin.com' }
    ];

    externalLinks.forEach((link) => {
      cy.get('footer').should('be.visible');
      cy.get(link.selector)
        .should('be.visible')
        .should('have.attr', 'href')
        .and('include', link.expectedUrl);
      cy.get(link.selector).should('have.attr', 'target', '_blank');
      cy.get(link.selector).should('have.attr', 'rel', 'noopener noreferrer');
    });
  });

  it('should maintain footer visibility and functionality across different screen sizes', () => {
    const viewports = [
      { width: 1920, height: 1080, name: 'desktop' },
      { width: 768, height: 1024, name: 'tablet' },
      { width: 375, height: 667, name: 'mobile' }
    ];

    viewports.forEach((viewport) => {
      cy.viewport(viewport.width, viewport.height);
      cy.visit('/');
      cy.get('footer').should('be.visible');
      cy.get('footer a').should('have.length.greaterThan', 0);
      cy.get('footer a').first().should('be.visible').click();
      cy.url().should('not.equal', Cypress.config().baseUrl + '/');
    });
  });

  it('should handle footer link edge cases and error states', () => {
    cy.get('footer').should('be.visible');
    cy.get('footer a').each(($link) => {
      cy.wrap($link).should('have.attr', 'href');
      cy.wrap($link).should('not.have.attr', 'href', '');
      cy.wrap($link).should('not.have.attr', 'href', '#');
      cy.wrap($link).should('have.css', 'cursor', 'pointer');
      cy.wrap($link).should('not.have.class', 'disabled');
    });
  });

  it('should verify footer links are keyboard accessible', () => {
    cy.get('footer a').first().focus();
    cy.focused().should('have.attr', 'href');
    cy.focused().should('have.css', 'outline').and('not.equal', 'none');
    cy.focused().type('{enter}');
    cy.url().should('not.equal', Cypress.config().baseUrl + '/');
  });

  it('should verify footer links have proper semantic HTML structure', () => {
    cy.get('footer').within(() => {
      cy.get('a').each(($link) => {
        cy.wrap($link).should('have.attr', 'href');
        cy.wrap($link).invoke('text').should('not.be.empty');
        cy.wrap($link).should('have.attr', 'aria-label').or('have.text');
      });
    });
    cy.get('footer nav').should('exist');
  });
});
